css:
.wrap{ width: 100%; max-width: 1484px; margin-left: auto; margin-right: auto; padding-left: 40px; padding-right: 40px; box-sizing: border-box; }
@media screen and (max-width: 767px){.wrap{ padding-left: 20px; padding-right: 20px; }}
.site-footer { padding-top: 48px; padding-bottom: 40px; border-top: 1px solid rgba(255, 255, 255, 0.4); background-color: #13181d; color: #ffffff; font-family: Switzer, Arial, sans-serif; }
.footer-top { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 40px; }
.footer-cols { display: flex; flex-wrap: wrap; gap: 140px; }
.footer-links { display: flex; flex-direction: column; gap: 14px; margin: 0; padding: 0; list-style: none; }
.footer-links-item { margin: 0; padding: 0; }
.footer-link { display: inline-flex; align-items: flex-start; gap: 3px; font-size: 20px; line-height: 1.2; color: #ffffff; text-decoration: none; }
.footer-link:hover { text-decoration: underline; text-underline-offset: 4px; }
.footer-link-icon { display: block; width: 11px; height: 11px; margin-top: 2px; }
.footer-legal { display: flex; flex-direction: column; gap: 14px; max-width: 260px; }
.footer-copyright { margin: 0; font-size: 15px; line-height: 1.3; }
.footer-legal-link { font-size: 15px; line-height: 1.3; color: #ffffff; text-decoration: none; }
.footer-legal-link:hover { text-decoration: underline; text-underline-offset: 4px; }
.footer-bottom { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; margin-top: 160px; }
.footer-tagline { margin: 0; font-size: 104px; line-height: 1.02; font-weight: 400; letter-spacing: -0.02em; }
.footer-sprinkle { display: block; flex: none; width: 28px; height: 30px; }

@media screen and (max-width: 991px) {
  .footer-cols { gap: 80px; }
  .footer-tagline { font-size: 72px; }
  .footer-bottom { margin-top: 120px; }
}
@media screen and (max-width: 767px) {
  .footer-top { flex-direction: column; gap: 48px; }
  .footer-cols { gap: 48px; }
  .footer-link { font-size: 18px; }
  .footer-tagline { font-size: 48px; }
  .footer-bottom { margin-top: 88px; }
}
@media screen and (max-width: 479px) {
  .footer-tagline { font-size: 38px; }
}
